<?php
namespace ExcelHerbal\ERP7\Organization;
use ExcelHerbal\ERP7\Database\Db;use ExcelHerbal\ERP7\Database\Transaction;use ExcelHerbal\ERP7\Domain\DomainException;use ExcelHerbal\ERP7\Security\Actor;use ExcelHerbal\ERP7\Security\Audit;use ExcelHerbal\ERP7\Security\BranchAuthority;use ExcelHerbal\ERP7\Security\Capabilities;use ExcelHerbal\ERP7\Security\Guard;
final class OrganizationService{
 public static function branches(Actor $a):array{if(!$a->branchIds)return[];$ids=implode(',',array_map('intval',$a->branchIds));return(array)Db::wpdb()->get_results(Db::wpdb()->prepare("SELECT id,code,name,is_head_office,status FROM ".Db::table('branches')." WHERE company_id=%d AND id IN ({$ids}) AND status='active' ORDER BY is_head_office DESC,name",$a->companyId),ARRAY_A);}
 public static function createBranch(Actor $a,string $code,string $name,bool $headOffice=false):array{Guard::cap($a,Capabilities::BRANCH_MANAGE);$code=strtoupper(trim($code));$name=trim($name);if($code===''||$name==='')throw new DomainException('Branch code and name are required.');return Transaction::run(function()use($a,$code,$name,$headOffice){$db=Db::wpdb();$t=Db::table('branches');Db::mustInsert($db,$t,['company_id'=>$a->companyId,'code'=>$code,'name'=>$name,'is_head_office'=>$headOffice?1:0,'status'=>'active','created_at'=>Db::now()]);if(!$db->insert_id)throw new DomainException('Branch code already exists.','branch_duplicate',409);$id=(int)$db->insert_id;Db::mustInsert($db,Db::table('employee_branch_authorities'),['company_id'=>$a->companyId,'employee_id'=>$a->employeeId,'branch_id'=>$id,'active'=>1,'granted_by'=>$a->employeeId,'valid_from'=>Db::now(),'valid_until'=>null]);Audit::add($a,'branch.create','branch',$id,['branch_id'=>$id,'code'=>$code,'creator_authority_bootstrapped'=>true]);return['id'=>$id,'code'=>$code,'name'=>$name,'status'=>'active'];});}
 public static function employees(Actor $a,int $branch):array{Guard::branch($a,$branch,Capabilities::EMP_VIEW);return(array)Db::wpdb()->get_results(Db::wpdb()->prepare("SELECT id,employee_code,full_name,mobile,email,designation_code,assigned_branch_id,reporting_employee_id,monthly_salary,status FROM ".Db::table('employees')." WHERE company_id=%d AND assigned_branch_id=%d AND status='active' ORDER BY full_name",$a->companyId,$branch),ARRAY_A);}
 public static function createEmployee(Actor $a,array $data):array{$branch=(int)($data['assigned_branch_id']??0);Guard::branch($a,$branch,Capabilities::EMP_MANAGE);$code=strtoupper(trim((string)($data['employee_code']??'')));$name=trim((string)($data['full_name']??''));$designation=strtoupper(trim((string)($data['designation_code']??'')));if($code===''||$name===''||$designation==='')throw new DomainException('Employee code, name and designation are required.');$db=Db::wpdb();$validDes=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('designations')." WHERE company_id=%d AND code=%s AND status='active'",$a->companyId,$designation));if(!$validDes)throw new DomainException('Active designation not found.','designation_invalid',422);$reporting=isset($data['reporting_employee_id'])?(int)$data['reporting_employee_id']:null;if($reporting){$ok=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('employees')." WHERE company_id=%d AND id=%d AND status='active'",$a->companyId,$reporting));if(!$ok)throw new DomainException('Reporting employee not found.','reporting_employee_invalid',422);}return Transaction::run(function()use($a,$data,$branch,$code,$name,$designation,$reporting){$db=Db::wpdb();Db::mustInsert($db,Db::table('employees'),['company_id'=>$a->companyId,'employee_code'=>$code,'wp_user_id'=>isset($data['wp_user_id'])?(int)$data['wp_user_id']:null,'designation_code'=>$designation,'assigned_branch_id'=>$branch,'reporting_employee_id'=>$reporting,'full_name'=>$name,'mobile'=>trim((string)($data['mobile']??''))?:null,'email'=>trim((string)($data['email']??''))?:null,'monthly_salary'=>max(0,(float)($data['monthly_salary']??0)),'joining_date'=>trim((string)($data['joining_date']??''))?:Db::today(),'status'=>'active','created_at'=>Db::now()]);if(!$db->insert_id)throw new DomainException('Employee code or WordPress user is already linked.','employee_duplicate',409);$id=(int)$db->insert_id;Db::mustInsert($db,Db::table('employee_branch_history'),['company_id'=>$a->companyId,'employee_id'=>$id,'branch_id'=>$branch,'effective_from'=>trim((string)($data['joining_date']??''))?:Db::today(),'effective_to'=>null,'reason'=>'Employee onboarding','changed_by'=>$a->employeeId,'created_at'=>Db::now()]);foreach((array)($data['role_ids']??[]) as$roleId){$rid=(int)$roleId;$ok=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('roles')." WHERE id=%d AND company_id=%d AND active=1",$rid,$a->companyId));if(!$ok)throw new DomainException('Invalid role assignment.','role_invalid',422);Db::mustInsert($db,Db::table('employee_roles'),['company_id'=>$a->companyId,'employee_id'=>$id,'role_id'=>$rid,'active'=>1,'assigned_by'=>$a->employeeId,'assigned_at'=>Db::now()]);}Audit::add($a,'employee.create','employee',$id,['branch_id'=>$branch,'designation'=>$designation]);return['id'=>$id,'employee_code'=>$code,'status'=>'active'];});}
 public static function transferEmployee(Actor $a,int $employeeId,int $newBranch,string $effectiveDate,string $reason):array{
  if(strlen(trim($reason))<5)throw new DomainException('Transfer reason is required.');
  $db=Db::wpdb();
  $e=$db->get_row($db->prepare("SELECT * FROM ".Db::table('employees')." WHERE id=%d AND company_id=%d AND status='active'",$employeeId,$a->companyId),ARRAY_A);
  if(!$e)throw new DomainException('Employee not found.','employee_not_found',404);
  $old=(int)$e['assigned_branch_id'];
  Guard::branch($a,$old,Capabilities::EMP_MANAGE);
  Guard::branch($a,$newBranch,Capabilities::EMP_MANAGE);
  if($old===$newBranch)throw new DomainException('Employee is already assigned to this branch.');
  $date=trim($effectiveDate)?:Db::today();
  $parsed=\DateTimeImmutable::createFromFormat('!Y-m-d',$date);
  if(!$parsed||$parsed->format('Y-m-d')!==$date)throw new DomainException('Transfer effective date must be YYYY-MM-DD.','transfer_date_invalid',422);
  if($date>Db::today())throw new DomainException('Future-dated primary branch transfer is not supported until a scheduled-transfer executor is enabled.','future_transfer_not_supported',422);
  $history=Db::table('employee_branch_history');
  $open=$db->get_row($db->prepare("SELECT id,effective_from FROM {$history} WHERE company_id=%d AND employee_id=%d AND effective_to IS NULL ORDER BY effective_from DESC,id DESC LIMIT 1",$a->companyId,$employeeId),ARRAY_A);
  if($open&&$date<=(string)$open['effective_from'])throw new DomainException('Transfer date must be after the current branch assignment start date.','transfer_date_conflict',409);
  return Transaction::run(function()use($a,$employeeId,$old,$newBranch,$date,$reason,$history){
   $db=Db::wpdb();
   $db->query($db->prepare("UPDATE {$history} SET effective_to=DATE_SUB(%s,INTERVAL 1 DAY) WHERE company_id=%d AND employee_id=%d AND effective_to IS NULL",$date,$a->companyId,$employeeId));
   Db::mustInsert($db,$history,['company_id'=>$a->companyId,'employee_id'=>$employeeId,'branch_id'=>$newBranch,'effective_from'=>$date,'effective_to'=>null,'reason'=>$reason,'changed_by'=>$a->employeeId,'created_at'=>Db::now()]);
   if(!$db->insert_id)throw new DomainException('Employee branch history could not be recorded.','employee_transfer_history_failed',500);
   $updated=$db->update(Db::table('employees'),['assigned_branch_id'=>$newBranch,'updated_at'=>Db::now()],['id'=>$employeeId,'company_id'=>$a->companyId]);
   if($updated===false)throw new DomainException('Employee primary branch could not be updated.','employee_transfer_update_failed',500);
   Audit::add($a,'employee.transfer_branch','employee',$employeeId,['branch_id'=>$newBranch,'from_branch_id'=>$old,'effective_date'=>$date,'reason'=>$reason]);
   return['id'=>$employeeId,'assigned_branch_id'=>$newBranch,'effective_date'=>$date];
  });
 }
 public static function employeeHistory(Actor $a,int $employeeId):array{$db=Db::wpdb();$e=$db->get_row($db->prepare("SELECT assigned_branch_id FROM ".Db::table('employees')." WHERE id=%d AND company_id=%d",$employeeId,$a->companyId),ARRAY_A);if(!$e)throw new DomainException('Employee not found.','employee_not_found',404);Guard::branch($a,(int)$e['assigned_branch_id'],Capabilities::EMP_VIEW);return(array)$db->get_results($db->prepare("SELECT h.*,b.code branch_code,b.name branch_name FROM ".Db::table('employee_branch_history')." h JOIN ".Db::table('branches')." b ON b.id=h.branch_id WHERE h.company_id=%d AND h.employee_id=%d ORDER BY h.effective_from DESC,h.id DESC",$a->companyId,$employeeId),ARRAY_A);}
 public static function designations(Actor $a):array{Guard::cap($a,Capabilities::EMP_VIEW);$db=Db::wpdb();return(array)$db->get_results($db->prepare("SELECT id,code,name,sequence_no,field_role,status FROM ".Db::table('designations')." WHERE company_id=%d AND status='active' ORDER BY sequence_no,name",$a->companyId),ARRAY_A);}
 public static function roles(Actor $a):array{Guard::cap($a,Capabilities::EMP_MANAGE);$db=Db::wpdb();return(array)$db->get_results($db->prepare("SELECT id,code,name FROM ".Db::table('roles')." WHERE company_id=%d AND active=1 ORDER BY name",$a->companyId),ARRAY_A);}
 public static function masterData(Actor $a):array{Guard::cap($a,Capabilities::ACCESS);$db=Db::wpdb();$p=(array)$db->get_results($db->prepare("SELECT id,sku,name,uom,batch_tracking,expiry_tracking FROM ".Db::table('products')." WHERE company_id=%d AND status='active' ORDER BY name",$a->companyId),ARRAY_A);$s=(array)$db->get_results($db->prepare("SELECT id,name,mobile,gstin FROM ".Db::table('suppliers')." WHERE company_id=%d AND status='active' ORDER BY name",$a->companyId),ARRAY_A);$acc=(array)$db->get_results($db->prepare("SELECT id,code,name,type,subtype FROM ".Db::table('accounts')." WHERE company_id=%d AND active=1 ORDER BY code",$a->companyId),ARRAY_A);return['products'=>$p,'suppliers'=>$s,'accounts'=>$acc];}
 public static function createProduct(Actor $a,array $data):array{Guard::cap($a,Capabilities::PRODUCT_MANAGE);$sku=strtoupper(trim((string)($data['sku']??'')));$name=trim((string)($data['name']??''));$mode=(string)($data['batch_tracking']??'optional');if($sku===''||$name===''||!in_array($mode,['off','optional','required'],true))throw new DomainException('Valid SKU, name and batch mode are required.');return Transaction::run(function()use($a,$data,$sku,$name,$mode){$db=Db::wpdb();Db::mustInsert($db,Db::table('products'),['company_id'=>$a->companyId,'sku'=>$sku,'name'=>$name,'uom'=>strtoupper(trim((string)($data['uom']??'PCS')))?:'PCS','batch_tracking'=>$mode,'expiry_tracking'=>!empty($data['expiry_tracking'])?1:0,'status'=>'active','created_at'=>Db::now()]);if(!$db->insert_id)throw new DomainException('Product SKU already exists.','product_duplicate',409);$id=(int)$db->insert_id;self::commercialRevision($a,$id,$data,'Initial commercial values');Audit::add($a,'product.create','product',$id,['sku'=>$sku]);return['id'=>$id,'sku'=>$sku,'status'=>'active'];});}
 public static function commercialRevision(Actor $a,int $productId,array $data,string $reason=''):array{Guard::cap($a,Capabilities::PRODUCT_MANAGE);$db=Db::wpdb();$p=$db->get_row($db->prepare("SELECT id FROM ".Db::table('products')." WHERE id=%d AND company_id=%d AND status='active'",$productId,$a->companyId),ARRAY_A);if(!$p)throw new DomainException('Active product not found.','product_not_found',404);$fields=['mrp','sale_price','ho_amount','bm_profit','salary_fund','office_expense','points','purchase_cost'];$values=[];foreach($fields as$f){$v=(float)($data[$f]??0);if($v<0)throw new DomainException('Commercial values cannot be negative.');$values[$f]=$v;}$effective=trim((string)($data['effective_from']??''))?:Db::now();Db::mustInsert($db,Db::table('product_commercial_revisions'),['company_id'=>$a->companyId,'product_id'=>$productId,'effective_from'=>$effective]+$values+['reason'=>trim($reason?:((string)($data['reason']??'')))?:null,'status'=>'active','approved_by'=>$a->employeeId,'created_at'=>Db::now()]);$id=(int)$db->insert_id;Audit::add($a,'product.commercial_revision','product',$productId,['revision_id'=>$id,'effective_from'=>$effective,'reason'=>$reason]);return['id'=>$id,'product_id'=>$productId,'effective_from'=>$effective];}
 public static function commercialHistory(Actor $a,int $productId):array{Guard::cap($a,Capabilities::PRODUCT_VIEW);$db=Db::wpdb();return(array)$db->get_results($db->prepare("SELECT * FROM ".Db::table('product_commercial_revisions')." WHERE company_id=%d AND product_id=%d ORDER BY effective_from DESC,id DESC",$a->companyId,$productId),ARRAY_A);}
 public static function setBranchAuthority(Actor $a,int $employeeId,int $branch,bool $active):array{Guard::branch($a,$branch,Capabilities::ACCESS_MANAGE);$db=Db::wpdb();$e=$db->get_var($db->prepare("SELECT id FROM ".Db::table('employees')." WHERE id=%d AND company_id=%d",$employeeId,$a->companyId));if(!$e)throw new DomainException('Employee not found.','employee_not_found',404);$t=Db::table('employee_branch_authorities');$r=$db->get_row($db->prepare("SELECT id FROM {$t} WHERE company_id=%d AND employee_id=%d AND branch_id=%d",$a->companyId,$employeeId,$branch),ARRAY_A);$data=['active'=>$active?1:0,'granted_by'=>$a->employeeId,'valid_from'=>Db::now(),'valid_until'=>null];if($r)$db->update($t,$data,['id'=>(int)$r['id']]);elseDb::mustInsert($db,$t,['company_id'=>$a->companyId,'employee_id'=>$employeeId,'branch_id'=>$branch]+$data);Audit::add($a,'branch_authority.'.($active?'grant':'revoke'),'employee',$employeeId,['branch_id'=>$branch]);return['employee_id'=>$employeeId,'branch_id'=>$branch,'active'=>$active,'branch_ids'=>BranchAuthority::ids($employeeId,$a->companyId)];}
}
